import('./server.mjs').then(async ({listTools, callTool}) => {
  // 1. List tools
  const tools = await listTools();
  console.log('tools:', tools.map(t => t.name).join(','));

  // 2. Unknown tool
  try { await callTool('fly', {}); console.log('FAIL: unknown tool did not throw'); }
  catch (e) { console.log('unknown tool rejected:', e.message); }

  // 3. Missing field
  try { await callTool('calculate', {a:1, operation:'add'}); console.log('FAIL: missing b did not throw'); }
  catch (e) { console.log('missing field rejected:', e.message); }

  // 4. Extra field
  try { await callTool('calculate', {a:1, b:2, operation:'add', extra:'x'}); console.log('FAIL: extra field did not throw'); }
  catch (e) { console.log('extra field rejected:', e.message); }

  // 5. Unsupported operation
  try { await callTool('calculate', {a:1, b:2, operation:'mod'}); console.log('FAIL: mod did not throw'); }
  catch (e) { console.log('bad enum rejected:', e.message); }

  // 6. Wrong type
  try { await callTool('calculate', {a:'x', b:2, operation:'add'}); console.log('FAIL: string a did not throw'); }
  catch (e) { console.log('bad type rejected:', e.message); }

  // 7. Division by zero
  try { await callTool('calculate', {a:10, b:0, operation:'divide'}); console.log('FAIL: div/0 did not throw'); }
  catch (e) { console.log('div by zero rejected:', e.message); }

  // 8. All four ops
  for (const [op,a,b,exp] of [['add',5,3,8],['subtract',5,3,2],['multiply',5,3,15],['divide',10,4,2.5]]) {
    const r = await callTool('calculate', {a,b,operation:op});
    console.log(op, '=>', r.content[0].text, exp===parseFloat(r.content[0].text)?'OK':'FAIL');
  }
});
